  quests: [
    { id: "biarritzgrandeplage", cat: "gor", area: "merkez", title: "Stroll the Grande Plage at Biarritz",
      desc: "The central beach of Biarritz, framed by the Hôtel du Palais at one end and the Rocher de la Vierge at the other. Striped bathing tents line the sand from early June, and the casino and Miramar beach sit next to it.",
      tip: "Walk the promenade at sunset for the best light. Lifeguards are on duty in summer; surf can be strong at mid-tide.", q: "Grande Plage, Quai de la Grande Plage, Biarritz", tags: ["free"], src: ["https://www.tourisme.biarritz.fr/en/beaches/grande-plage", "https://www.lonelyplanet.com/points-of-interest/grande-plage/1196372"] },
    { id: "biarritzrocher", cat: "gor", area: "merkez", title: "Cross the footbridge to the Rocher de la Vierge",
      desc: "A rocky islet joined to the mainland by a footbridge built under Napoleon III, who planned to anchor a harbour breakwater here. A tunnel was cut through the rock in 1864 and a statue of the Virgin was raised on top in 1865.",
      tip: "Best at sunset or when Atlantic swells break against the rock. The bridge can be closed in storms.", q: "Rocher de la Vierge, Esplanade du Rocher de la Vierge, Biarritz", tags: ["free"], src: ["https://www.tourisme64.com/nos-destinations/pays-basque/incontournables-du-pays-basque/le-rocher-de-la-vierge/", "https://www.routard.com/guide_voyage_lieu/10233-rocher_de_la_vierge.htm"] },
    { id: "citedelocean", cat: "gor", area: "merkez", title: "Explore the Cité de l'Océan et du Surf",
      desc: "A science and ocean museum designed by Steven Holl, opened in 2011 with exhibits on ocean history, marine biology and surf culture. It is part of the Biarritz Océan complex with the Musée de la Mer.",
      tip: "A combined ticket with the aquarium is available. Check winter closing days before going.", q: "Cité de l'Océan, 1 avenue de la Plage, Biarritz", tags: ["rainy day"], src: ["https://fr.wikipedia.org/wiki/Cité_de_l'Océan"] },
    { id: "biarritzaquarium", cat: "gor", area: "merkez", title: "Meet the seals at the Musée de la Mer aquarium",
      desc: "An Art Deco aquarium on the Plateau de l'Atalaye facing the Rocher de la Vierge, opened on 10 August 1933. Tanks hold sharks, reef fish and Atlantic species, and grey seals are fed daily.",
      tip: "Seal feeding is listed at 10:30 and 17:00; confirm times on the museum site.", q: "Musée de la Mer, Esplanade du Rocher de la Vierge, Biarritz", tags: ["rainy day"], src: ["https://tourisme.biarritz.fr/en/discover/sites-and-museums/musee-de-la-mer", "https://www.lonelyplanet.com/points-of-interest/musee-de-la-mer/418961"] },
    { id: "biarritzphare", cat: "gor", area: "merkez", title: "Climb the 248 steps of the Biarritz lighthouse",
      desc: "The Phare de la Pointe Saint-Martin was built from 1830 and lit in 1834 to guide ships towards the mouth of the Adour. A spiral stair leads to a 360-degree view of the Basque coast, the Landes and the Pyrenees.",
      tip: "Book the ticket online via the Biarritz tourist office; hours vary by season.", q: "Phare de Biarritz, Rue du Phare, Biarritz", src: ["https://www.routard.com/fr/guide/france/pays-basque-et-bearn/pyrenees-atlantiques/biarritz/phare-de-la-pointe-saint-martin", "https://www.tourisme64.com/activites/biarritz/PCUAQU064FS0000F-phare-de-biarritz/"] },
    { id: "chapelleimperiale", cat: "gor", area: "merkez", title: "Step into the Chapelle Impériale",
      desc: "Built in 1864-65 for Empress Eugénie by the architect Boeswillwald, a pupil of Viollet-le-Duc. Its romano-Byzantine and Hispano-Moorish style recalls her Spanish origins, and it is dedicated to Our Lady of Guadalupe.",
      tip: "Open mainly for guided visits; check with the tourist office (05 59 22 37 10).", q: "Chapelle Impériale, Avenue de l'Impératrice, Biarritz", src: ["https://www.cheminsdememoire.gouv.fr/en/biarritz-imperial-chapel", "https://tourisme.biarritz.fr/en/discover/sites-and-museums-biarritz/imperial-chapel"] },
    { id: "eglisesainteeugenie", cat: "gor", area: "merkez", title: "See the neo-Gothic Église Sainte-Eugénie",
      desc: "A neo-Gothic church on the Port-Vieux, dedicated to the patron saint of Empress Eugénie, with a bell tower facing the ocean. Routard dates the present building to 1898-1903 by Jean-Baptiste Ernest Lacombe, replacing an 1856 chapel.",
      tip: "A restoration campaign is under way, so scaffolding may be present. Combine with the nearby Port-Vieux beach.", q: "Église Sainte-Eugénie, Place Sainte-Eugénie, Biarritz", tags: ["free"], src: ["https://www.routard.com/fr/guide/france/pays-basque-et-bearn/pyrenees-atlantiques/biarritz/eglise-sainte-eugenie", "https://structurae.net/structures/eglise-sainte-eugenie-de-biarritz"] },
    { id: "biarritzportpecheurs", cat: "gor", area: "merkez", title: "Wander the Port des Pêcheurs and its crampottes",
      desc: "The old fishing harbour at the foot of the Atalaye, dating to a 1780 slipway and an 1865 port under Napoleon III. Small wooden fishermen's huts, the crampottes, line the quay.",
      tip: "Come at golden hour. The port holds a Saturday festival with sardine grills in July and August.", q: "Port des Pêcheurs, Allée du Port des Pêcheurs, Biarritz", tags: ["free"], src: ["https://www.routard.com/fr/mag/reportage/a/le-pays-basque-cote-ports-de-biarritz-a-hendaye", "https://www.waymarking.com/waymarks/wm16MF4_Le_port_de_pche_Biarritz_France"] },
    { id: "bayonnecathedral", cat: "gor", area: "merkez", title: "Admire Bayonne's Cathédrale Sainte-Marie",
      desc: "A Gothic cathedral with twin spires, classified as a historic monument in 1862, dominating the old town of Grand Bayonne. It is a stop on the Camino de Santiago route.",
      tip: "Entry is free; mind services and the guided tours of the building works.", q: "Cathédrale Sainte-Marie, Place Pasteur, Bayonne", tags: ["free", "rainy day"], src: ["https://www.techno-science.net/fr/definitions/cathedrale-sainte-marie-de-bayonne", "https://www.lonelyplanet.fr/poi/pays-basque-biarritzbayonneetangpaysbasqueess-cathedrale-sainte-marie"] },
    { id: "bayonnecloister", cat: "gor", area: "merkez", title: "Walk the cathedral cloister in Bayonne",
      desc: "A rectangular 13th-14th century cloister on the south side of the cathedral, among the largest in France. It served for prayer, processions and burials, and the engraved floor slabs remain.",
      tip: "Entry is free; check opening hours as they vary.", q: "Cloître de la cathédrale, Rue Albert 1er, Bayonne", tags: ["free"], src: ["https://www.guide-tourisme-france.com/VISITER/cloitre--bayonne-5714.htm", "https://www.cityzeum.com/cloitre"] },
    { id: "musebasquebayonne", cat: "gor", area: "merkez", title: "Learn Basque life at the Musée Basque",
      desc: "The Basque museum has occupied the late 16th century Maison Dagourette in Petit Bayonne since 1924. Twenty rooms on three levels cover ethnography and history, including a relief model of the port of Bayonne.",
      tip: "Open Tuesday to Sunday; closed Mondays. Check the museum website for current prices.", q: "Musée Basque et de l'histoire de Bayonne, 37 Quai des Corsaires, Bayonne", tags: ["rainy day"], src: ["https://www.en-pays-basque.fr/en/visit/musee-basque-et-de-lhistoire-de-bayonne/", "https://www.tourisme64.com/activites/bayonne/PCUAQU064FS00006-musee-basque-et-de-l-histoire-de-bayonne/"] },
    { id: "musebonnat", cat: "gor", area: "merkez", title: "See Ingres and old masters at Musée Bonnat-Helleu",
      desc: "The fine arts museum of Bayonne, created around painter Léon Bonnat's bequest, reopened in November 2025 after a 14-year renovation. Highlights include Ingres's La Baigneuse and many works on deposit from the Louvre.",
      tip: "Check current hours and tickets on the museum site; the new route doubled the exhibition space.", q: "Musée Bonnat-Helleu, 5 Rue Jacques Laffitte, Bayonne", tags: ["rainy day"], src: ["https://en.wikipedia.org/wiki/Mus%C3%A9e_Bonnat-Helleu", "https://www.theartnewspaper.com/2025/11/24/bayonnes-refreshed-bonnat-helleu-museum-reopens-after-major-renovation"] },
    { id: "bayonnechateauvieux", cat: "gor", area: "merkez", title: "Walk the Vauban ramparts to the Château-Vieux",
      desc: "The Château-Vieux stands on Gallo-Roman foundations reworked in the 11th century, and Vauban made it the northwest anchor of Bayonne's defences. The ramparts walk gives views over rooftops, the Nive and the cathedral.",
      tip: "The castle is seen from outside; the fortifications have been listed since 1886.", q: "Château-Vieux, Rue des Remparts, Bayonne", tags: ["free"], src: ["https://en.wikipedia.com/wiki/Ch%C3%A2teau-Vieux_(Bayonne)", "https://monumentum.fr/monument-historique/pa00084336/bayonne-fortifications"] },
    { id: "villabelza", cat: "gor", area: "merkez", title: "Photograph Villa Belza above the Côte des Basques",
      desc: "A château-like villa built in the late 19th century between the Rocher de la Vierge and the Côte des Basques, later damaged by fire and left abandoned before being renovated into apartments.",
      tip: "It is private; view it from the coastal path. Pair with a Côte des Basques walk.", q: "Villa Belza, Rue Gardères, Biarritz", tags: ["free"], src: ["https://www.guide-tourisme-france.com/VISITER/villa-belza--biarritz-6012.htm", "https://www.barnes-cotebasque.com/en/news/basque-country-culture-5/villa-belza-biarritz-571"] },
    { id: "chambredamourgrotte", cat: "gor", area: "merkez", title: "Find the Chambre d'Amour cave in Anglet",
      desc: "A natural cave in the cliffs of Cap Saint-Martin, visible only at low tide, linked to the legend of two lovers swept away by the rising sea. The district of Anglet takes its name from it.",
      tip: "Check the tide table. Going inside is discouraged for safety.", q: "Grotte de la Chambre d'Amour, Chambre d'Amour, Anglet", tags: ["free"], src: ["https://www.guide-tourisme-france.com/VISITER/grotte-chambre-amour--anglet-4342.htm", "https://www.surf-report.com/news/culture-musique/anglet-chambre-amour-conte-histoire-830217492.html"] },
    { id: "atelierchocolatbayonne", cat: "gor", area: "merkez", title: "Tour the Musée du Chocolat of L'Atelier du Chocolat",
      desc: "The museum at the house's historic base in Bayonne traces cocoa's origins, its arrival in Bayonne and the old workshop machines, ending with a tasting.",
      tip: "Visits are by appointment; allow about 1h30.", q: "L'Atelier du Chocolat, 7 Allée de Gibéléou, Bayonne", tags: ["rainy day"], src: ["https://www.tourisme64.com/activites/bayonne/PCUAQU064FS0008O-l-atelier-du-chocolat-musee-du-chocolat/", "https://www.guide-tourisme-france.com/VISITER/atelier-chocolat--bayonne-5870.htm"] },
    { id: "cazenavebayonne", cat: "ye", area: "merkez", title: "Drink frothy hot chocolate at Cazenave",
      desc: "A chocolate maker and tea room under the arcades of rue Port-Neuf, producing chocolate since 1854. Its hot chocolate is hand-whisked to a foam and served with buttered brioche.",
      tip: "Order the chocolat mousseux with the Chocolat Toast. Closed Sundays and probably Mondays; confirm.", q: "Chocolat Cazenave, 19 Rue Port-Neuf, Bayonne", kind: "sweet", src: ["https://fr.gaultmillau.com/fr/artisans/chocolat-cazenave", "https://www.nationalgeographic.com/travel/article/drinking-chocolate-in-bayonne"] },
    { id: "ibaialdebayonne", cat: "ye", area: "merkez", title: "Taste Bayonne ham at Pierre Ibaïalde",
      desc: "A ham workshop and boutique in Petit Bayonne selling its own jambon, Espelette sausage and veal axoa. Guided visits of about 45 minutes end with a tasting.",
      tip: "Book the tour online, especially in July and August.", q: "Pierre Ibaïalde, 41 Rue des Cordeliers, Bayonne", kind: "meal", src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/artisans-visites-et-ateliers-/bayonne-52/pierre-ibaialde-1613.html", "https://www.en-pays-basque.fr/en/sit/pierre-ibaialde-artisan-du-jambon-a-bayonne/"] },
    { id: "miremontbiarritz", cat: "ye", area: "merkez", title: "Have macarons and tea at Miremont",
      desc: "A pâtisserie and tea room on Place Clemenceau, opened in 1872 by Etienne Singher. Known for its macarons, gâteau basque and hot chocolate with Chantilly.",
      tip: "Sit in the historic salon. Open daily around 9:00-19:00; check ahead.", q: "Pâtisserie Miremont, 1 bis Place Georges Clemenceau, Biarritz", kind: "sweet", src: ["https://fr.gaultmillau.com/fr/artisans/patisserie-miremont", "https://monumentum.fr/monument-historique/pa64000060/biarritz-patisserie-miremont"] },
    { id: "halleseaillerie", cat: "ye", area: "merkez", title: "Eat oysters at L'Ecaillerie in the Halles de Biarritz",
      desc: "The covered Halles market opened in 1885 and was restored in 2013. L'Ecaillerie is a seafood stall where you can buy oysters and eat them with white wine upstairs.",
      tip: "Go at market time, morning to early afternoon. Summer evenings have a night market.", q: "L'Ecaillerie, Les Halles, rue des Halles, Biarritz", kind: "snack", src: ["https://api-adresse.data.gouv.fr/search/?q=Rue des Halles Biarritz"] },
    { id: "chezalbertbiarritz", cat: "ye", area: "merkez", title: "Order wild fish at Chez Albert on the port",
      desc: "A harbour-side seafood restaurant at the Port des Pêcheurs known for wild fish from the Basque coast, with a terrace in spring and summer.",
      tip: "Book ahead; reportedly closed Wednesdays.", q: "Chez Albert, 51 bis Allée du Port des Pêcheurs, Biarritz", kind: "meal", src: ["https://indagare.com/restaurant/chez-albert", "https://fr.gaultmillau.com/en/restaurant/chez-albert"] },
    { id: "crampotte30", cat: "ye", area: "merkez", title: "Share pintxos with a harbour view at Crampotte 30",
      desc: "A tiny seasonal bar on the Port des Pêcheurs serving pintxos, local cheese, Basque sausage and txakoli. It has a small terrace and no indoor seating.",
      tip: "Open roughly late spring to early October; hours vary, so check.", q: "Crampotte 30, 30 Allée du Port des Pêcheurs, Biarritz", kind: "meal", src: ["https://indagare.com/restaurant/crampotte-30", "https://olivemagazine.com/travel/europe/france/biarritz-france-top-10-places-to-eat-and-drink"] },
    { id: "daranatzbayonne", cat: "ye", area: "merkez", title: "Buy gâteau basque at Daranatz",
      desc: "A Bayonne confectioner on rue Port-Neuf selling macarons, gâteaux basques and cannelés, founded in 1890.",
      tip: "Choose the cream or cherry gâteau basque.", q: "Daranatz, 15 Rue Port-Neuf, Bayonne", kind: "meal", src: ["https://www.guide-du-paysbasque.com/fr/tourisme/deguster/produits-basques/gateaux/bayonne-52/daranatz-4988.html", "https://www-lonelyplanet-com-57e2.imagizer.com/france/southwestern-france/bayonne/shopping/daranatz/a/poi-sho/430542/359291"] },
    { id: "pariesbayonne", cat: "ye", area: "merkez", title: "Try kanougas at Pariès on rue Port-Neuf",
      desc: "A confectioner founded in 1895 and now run by the fourth generation, known for kanougas, tourons and mouchous. Gault&Millau notes Pariès registered the kanouga name.",
      tip: "Buy a box of soft chocolate kanougas.", q: "Pariès, 14 Rue Port-Neuf, Bayonne", kind: "meal", src: ["https://fr.gaultmillau.com/en/artisans/paries", "https://www.tourisme64.com/en/8-gastronomic-specialties-in-the-basque-country-and-bearn/"] },
    { id: "adambiarritz", cat: "ye", area: "merkez", title: "Taste macarons at Maison Adam in Biarritz",
      desc: "A Biarritz shop of the Maison Adam, whose macarons trace to 1660 and Louis XIV's wedding at Saint-Jean-de-Luz. It sells macarons, Basque cakes and chocolates.",
      tip: "Climb the back staircase for a view toward the lighthouse.", q: "Maison Adam, 27 Place Georges Clemenceau, Biarritz", kind: "sweet", src: ["https://fr.gaultmillau.com/fr/artisans/maison-adam-64", "https://www.maisonadam.fr/en/"] },
    { id: "lesarcadesbayonne", cat: "ye", area: "merkez", title: "Eat pintxos under the arcades at Les Arcades",
      desc: "A Basque restaurant and pintxos bar at 40 rue Port-Neuf between the town hall and cathedral, serving market cuisine, pintxos and cassolettes.",
      tip: "Reported live music on Friday evenings; hours vary, so check.", q: "Les Arcades, 40 Rue Port-Neuf, Bayonne", kind: "meal", src: ["https://www.guide-du-paysbasque.com/fr/tourisme/se-restaurer/bars-a-vins-bieres-bistrot-tapas-et-pintxos/bayonne-52/les-arcades-7957.html", "https://www.guide-du-paysbasque.com/fr/tourisme/se-restaurer/restaurants/bayonne-52/les-arcades-3810.html"] },
    { id: "trinquetbrasseriebayonne", cat: "ye", area: "merkez", title: "Have tapas at the Brasserie du Trinquet Saint-André",
      desc: "A café-restaurant next to the Trinquet Saint-André pelota court, a gathering place for players and spectators and for Bayonne festivities.",
      tip: "Reviewers praise the tapas and the patio.", q: "Brasserie du Trinquet Saint-André, 4 Rue du Jeu de Paume, Bayonne", kind: "meal", src: ["https://www.guide-du-paysbasque.com/fr/tourisme/se-restaurer/restaurants/bayonne-52/brasserie-du-trinquet-saint-andre-1006.html", "https://www.lonelyplanet.fr/poi/pays-basque-biarritzbayonneetangpaysbasqueess-trinquet-saint-andre"] },
    { id: "barjeanbiarritz", cat: "ye", area: "merkez", title: "Order scallops with Espelette at Bar Jean",
      desc: "A tapas bar facing the Halles de Biarritz serving Basque and Spanish tapas and pintxos. Guides recommend the scallops with Espelette pepper.",
      tip: "No reservations; sit at the counter or on the terrace.", q: "Bar Jean, 5 Rue des Halles, Biarritz", kind: "drink", src: ["https://indagare.com/restaurant/bar-jean", "https://theculturetrip.com/europe/france/articles/10-of-biarritzs-top-tapas-bars"] },
    { id: "damejeannebayonne", cat: "ye", area: "merkez", title: "Sip natural wine at Dame Jeanne",
      desc: "A wine bar in Bayonne run by three owners who took over from Marie Hours, serving plant-forward small plates, local charcuterie and natural wines on tap.",
      tip: "Open mid-week to weekend; closed Monday and Tuesday per a listing.", q: "Dame Jeanne, 4 rue Port de Castets, Bayonne", kind: "drink", src: ["https://api-adresse.data.gouv.fr/search/?q=4 rue Port de Castets Bayonne"] },
    { id: "chisteracoquillages", cat: "ye", area: "merkez", title: "Eat Cancale oysters at Chistera & Coquillages",
      desc: "A seafood restaurant on rue des Halles near the market, offering pintxos, seafood platters, Cancale oysters and fish of the day; selected in Gault&Millau 2026.",
      tip: "Open long hours daily per some sources; confirm.", q: "Chistera & Coquillages, 13 Rue des Halles, Biarritz", kind: "snack", src: ["https://fr.gaultmillau.com/en/restaurant/chistera-et-coquillages", "https://www.guide-du-paysbasque.com/en/tourism/eating-and-drinking/restaurants/biarritz-53/chistera-et-coquillages-9304.html"] },
    { id: "surfcotedesbasques", cat: "dene", area: "merkez", title: "Take a surf lesson on the Côte des Basques",
      desc: "A long beach below the cliffs south of the town, a classic spot for beginners with long soft waves. Schools such as La Vague Basque, Lagoondy and Jo Moraiz run lessons.",
      tip: "The beach is reachable only at low tide; check tide coefficients. June and September are best for beginners.", q: "Plage de la Côte des Basques, Biarritz", months: [5, 6, 7, 8, 9, 10], src: ["https://www.tourisme64.com/activites/biarritz/PNAAQU064FS00032-la-cote-des-basques/", "https://www.manawa.com/en-GB/activity/france/biarritz/surfing/private-surf-lessons-on-the-cote-des-basques-beach-in-biarritz/25863"] },
    { id: "anglethecavaliers", cat: "dene", area: "merkez", title: "Watch or ride the waves at Les Cavaliers, Anglet",
      desc: "Anglet's best-known surf break, a beach of over 1 km with powerful tubular waves and schools on the sand. It hosts international junior surf contests.",
      tip: "Beginners are steered to Les Corsaires or La Madrague; the waves suit intermediates best.", q: "Plage des Cavaliers, Anglet", src: ["https://www.plages.tv/surf/spot/plage-des-cavaliers-anglet-64600", "https://vvanat.fr/blog/plage-surf-anglet/"] },
    { id: "voievertepignada", cat: "dene", area: "merkez", title: "Cycle the Voie Verte du Pignada in Anglet",
      desc: "A roughly 7 km cycle loop around the Pignada pine forest, starting from the Montbrun district, with a detour possible to the Dunes beach. Part of the forest burned in a fire on 30 July 2020.",
      tip: "Cycling is banned inside the forest, so stay on the marked cycle path. Allow about 2 hours.", q: "Voie verte du Pignada, Montbrun, Anglet", tags: ["free"], src: ["https://www.cirkwi.com/en/circuit/371014-voie-verte-du-pignada", "https://commune-mairie.fr/randonnee/voie-verte-du-pignada-8ba22ed046"] },
    { id: "fetesdebayonne", cat: "dene", area: "merkez", title: "Dress in red and white for the Fêtes de Bayonne",
      desc: "Bayonne's five-day summer festival, held mid-July in 2026 (15 to 19 July), with parades, bullfights and concerts across the old town.",
      tip: "Wear white with a red scarf and expect huge crowds; program at fetes.bayonne.fr.", q: "Hôtel de Ville, Place de la Liberté, Bayonne", months: [7], src: ["https://www.routard.com/guide_agenda_detail/2497/fetes_de_bayonne.htm", "https://onivapp.com/blog/fetes-de-bayonne-2026"] },
    { id: "thalassabiarritz", cat: "dene", area: "merkez", title: "Unwind at Thalassa Sea & Spa",
      desc: "The thalassotherapy centre of the Sofitel Biarritz Le Miramar, on Rue Louison Bobet, with seawater massages, hydro-relaxing sessions and marine wraps.",
      tip: "Book treatments ahead; other options include Thalmar on rue de Madrid.", q: "Thalassa Sea & Spa, 13 rue Louison Bobet, Biarritz", tags: ["rainy day"], src: ["https://api-adresse.data.gouv.fr/search/?q=13 rue Louison Bobet Biarritz"] },
    { id: "hallesbayonnemarket", cat: "dene", area: "merkez", title: "Browse the Halles de Bayonne market",
      desc: "A covered market on the Nive quay, rebuilt in 1994 on the model of the 1860 Baltard-style halls. Stalls sell foie gras, pâtés, sheep's cheese and spices; on Friday a flea market runs by the river, and on Saturday a producers' market.",
      tip: "Go Saturday morning for the producers' market; check hours.", q: "Halles de Bayonne, Quai Dominique Roquebert, Bayonne", tags: ["free"], src: ["https://www.guide-du-paysbasque.com/fr/experiences/gourmande/article-notre-top-5-des-plus-beaux-marches-du-pays-basque--234.html", "https://ryo.co/fr/destinations/france/lieux/halles-de-bayonne-et-maison-moulis/"] },
    { id: "izadiaanglet", cat: "dene", area: "merkez", title: "Walk the Izadia nature park at the Adour mouth",
      desc: "A Natura 2000 ecological park with two lakes at the mouth of the Adour, with a trail of ten stations on coastal wetland biodiversity and free guided walks.",
      tip: "Open Wednesday to Sunday per a 2025 programme; call 05 59 57 17 48.", q: "Parc écologique Izadia, 297 Avenue de l'Adour, Anglet", tags: ["free"], src: ["https://www.guide-du-paysbasque.com/en/tourism/discover/tourist-sites/nature-reserve/anglet-46/parc-ecologique-izadia-2841.html", "https://izadia.anglet.fr/wp-content/uploads/2025/04/izadia_prog_printemps_2025.pdf"] },
    { id: "golfbiarritzphare", cat: "dene", area: "merkez", title: "Play 18 holes at Golf de Biarritz Le Phare",
      desc: "Founded in 1888, one of the oldest golf clubs in France, set in the town with views of the ocean from parts of the course.",
      tip: "Green fees vary by season; book ahead (05 59 03 71 80).", q: "Golf de Biarritz Le Phare, 2 Avenue Edith Cavell, Biarritz", src: ["https://www.en-pays-basque.fr/en/activity/golf-de-biarritz-le-phare/", "https://www.where2golf.com/france/golf-de-biarritz-le-phare"] },
    { id: "angletchambredamourbeach", cat: "dene", area: "merkez", title: "Swim at Plage de la Chambre d'Amour in Anglet",
      desc: "An Anglet beach below the cliffs of Cap Saint-Martin and host of the Pro Anglet surf contest. The adjacent Petite Chambre d'Amour beach is quieter.",
      tip: "Swim in lifeguarded months; check tide and surf conditions.", q: "Plage de la Chambre d'Amour, Anglet", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/plages/anglet-46/plage-de-la-petite-chambre-d-amour-3558.html", "https://worldsurfleague.com/posts/139415/www.worldsurfleague.com/events/2015/mqs/1276/anglet-pro"] },
    { id: "trinquetsaintandre", cat: "dene", area: "merkez", title: "Watch a pelota match at the Trinquet Saint-André",
      desc: "One of the oldest pelota courts in France, in Petit Bayonne, hosting games and tournaments, mainly pala, outside the summer.",
      tip: "Matches usually on weekday evenings and weekend afternoons; check the schedule.", q: "Trinquet Saint-André, 9 Rue des Cordeliers, Bayonne", tags: ["rainy day"], src: ["https://www.guide-tourisme-france.com/VISITER/trinquet-saint-andre--bayonne-5991.htm", "https://www.lonelyplanet.fr/poi/pays-basque-biarritzbayonneetangpaysbasqueess-trinquet-saint-andre"] },
    { id: "portvieuxbeach", cat: "dene", area: "merkez", title: "Swim in the sheltered Port-Vieux cove",
      desc: "A small, sheltered cove beach below Église Sainte-Eugénie, protected from the swell and popular for family swimming.",
      tip: "Check tide times; it is small and crowded in summer.", q: "Plage du Port-Vieux, Biarritz", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/plages/biarritz-53/plage-du-port-vieux-6950.html", "https://www.tourisme64.com/activites/biarritz/PNAAQU064FS00032-la-cote-des-basques/"] },
    { id: "fetedupportpecheurs", cat: "dene", area: "merkez", title: "Join the Saturday port festival at the Port des Pêcheurs",
      desc: "The fishermen's harbour hosts a Saturday festival in July and August with music, sardine grills and concerts. The harbour declared itself a free commune on 7 June 1961.",
      tip: "Arrive early for sardines; it gets crowded.", q: "Port des Pêcheurs, Allée du Port des Pêcheurs, Biarritz", months: [7, 8], tags: ["free"], src: ["https://www.routard.com/fr/mag/reportage/a/le-pays-basque-cote-ports-de-biarritz-a-hendaye", "https://touradour.com/towns/biarritz/crampotte_biarritz.asp"] },
    { id: "arnagacambo", cat: "gor", area: "cevre", title: "Tour Edmond Rostand's neo-Basque Villa Arnaga",
      desc: "Villa Arnaga is the neo-Basque house that Cyrano de Bergerac author Edmond Rostand designed himself and moved into in 1906. It stands in 15 hectares of French and English-style gardens and has been owned by the town since 1962. It carries the Maisons des Illustres label.",
      tip: "Opening hours vary by season, so check arnaga.com first. Allow time for the gardens as well as the house.", q: "Villa Arnaga, Route du Docteur Camino, Cambo-les-Bains", tags: ["rainy day"], src: ["https://www.tourisme64.com/en/our-destinations/welcome-to-the-basque-country/must-sees-in-the-basque-country/villa-arnaga/", "https://www.livreshebdo.fr/article/la-villa-dedmond-rostand-recoit-le-label-maisons-des-illustres"] },
    { id: "abbadiahendaye", cat: "gor", area: "cevre", title: "Visit the cliff-top Château d'Abbadia in Hendaye",
      desc: "Neo-Gothic castle-observatory built from 1864 for the explorer and astronomer Antoine d'Abbadie, with Viollet-le-Duc credited as architect. It stands on the cliffs above the Basque coast and was left to the Académie des Sciences, which still owns it. The observatory worked until 1975.",
      tip: "Visits are guided and booking is advised; the grounds and coastal paths around it are the best part on a clear day.", q: "Château d'Abbadia, Corniche basque, Hendaye", tags: ["rainy day"], src: ["https://chateau-abbadia.fr/en", "https://saint-jean-de-luz.com/en/sit/abbadia-le-chateau-observatoire/"] },
    { id: "socoafort", cat: "gor", area: "cevre", title: "Walk around the Vauban fort at Socoa",
      desc: "Fort de Socoa guards the entrance to the bay of Saint-Jean-de-Luz. Work began under Henri IV, the Spanish held it in 1636, and Vauban later remodelled it. It is a listed monument and now belongs to the local communauté de communes.",
      tip: "Access to the interior is limited, but the base of the fort has a good panorama of the bay. Combine it with the quay and beach of Socoa.", q: "Fort de Socoa, Ciboure", tags: ["free"], src: ["https://monumentum.fr/monument-historique/pa00084380/ciboure-fort-du-socoa", "https://www.guide-tourisme-france.com/VISITER/fort-socoa--ciboure-37921.htm"] },
    { id: "sjdlsaintjeanbaptiste", cat: "gor", area: "cevre", title: "See the baroque altarpiece of Saint-Jean-Baptiste",
      desc: "This church in Saint-Jean-de-Luz is where Louis XIV married the Infanta Maria Theresa of Austria on 9 June 1660. Its gilded baroque retable fills the choir, and the nave has the typical Basque wooden galleries. It is listed as a monument historique.",
      tip: "Enter from rue Gambetta and look up at the galleries. Guided tours by the Pays d'art et d'histoire run on set dates.", q: "Église Saint-Jean-Baptiste, rue Gambetta, Saint-Jean-de-Luz", tags: ["free", "rainy day"], src: ["https://en.wikipedia.com/wiki/%C3%89glise_Saint-Jean-Baptiste_de_Saint-Jean-de-Luz", "https://www.pop.culture.gouv.fr/notice/merimee//PA00084494"] },
    { id: "maisonlouisxiv", cat: "gor", area: "cevre", title: "Step inside the house where Louis XIV stayed in 1660",
      desc: "Lohobiague-Enea, known as Maison Louis XIV, was built in 1643 for the shipowner Joannis de Lohobiague. Louis XIV lodged here in 1660 before his wedding. Visits are guided, with a maximum of about 20 to 25 people at a time.",
      tip: "Seasonal opening; check maison-louis-xiv.fr. The house is on place Louis XIV, beside the harbour.", q: "Maison Louis XIV, Place Louis XIV, Saint-Jean-de-Luz", tags: ["rainy day"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/sites-touristiques/chateaux/saint-jean-de-luz-75/maison-louis-xiv-2413.html", "https://www.lonelyplanet.fr/poi/pays-basque-cotebasqueetarriereppaysbasqueess-maison-louis-xiv"] },
    { id: "maisoninfantesjdl", cat: "gor", area: "cevre", title: "Look at the Maison de l'Infante on the quay",
      desc: "This brick-and-stone house on the harbour in Saint-Jean-de-Luz sheltered the Spanish Infanta Maria Theresa before her marriage to Louis XIV in 1660. It faces the Maison Louis XIV across the port quarter.",
      tip: "The house is best admired from the quay; check with the tourist office for visit days.", q: "Maison de l'Infante, Quai de l'Infante, Saint-Jean-de-Luz", tags: ["free"], src: ["https://www.routard.com/fr/guide/france/pays-basque-et-bearn/pyrenees-atlantiques/saint-jean-de-luz/maison-de-l-infante", "https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/sites-touristiques/chateaux/saint-jean-de-luz-75/la-maison-de-l-infante-2403.html"] },
    { id: "ainhoavillage", cat: "gor", area: "cevre", title: "Stroll the main street of Ainhoa",
      desc: "Ainhoa is a bastide-type village on the border of Labourd and Navarre, founded in the Middle Ages to host pilgrims heading to Santiago de Compostela. It is a member of Les Plus Beaux Villages de France, with white houses and red or green timbering lining one street.",
      tip: "Park at the entrance and walk the single street. Pair it with Espelette and Sare, which are close by.", q: "Ainhoa, Pyrénées-Atlantiques", tags: ["free"], src: ["https://www.tourisme64.com/nos-destinations/pays-basque/ainhoa/", "https://www.guide-du-paysbasque.com/fr/selon-mes-envies/culturelle/article-ainhoa--28.html"] },
    { id: "espelettevillage", cat: "gor", area: "cevre", title: "Photograph the pepper-draped houses of Espelette",
      desc: "Espelette is the home of the AOP piment d'Espelette. Its Labourd houses have white walls and red or green timber framing, and strings of peppers hang from the façades to dry from late summer into autumn. The village has a 17th and 18th century core.",
      tip: "Come between September and October for the full display of drying peppers. Weekday mornings are quieter.", q: "Espelette, Pyrénées-Atlantiques", tags: ["free"], src: ["https://www.tourisme64.com/nos-destinations/pays-basque/espelette/", "https://www.guide-du-paysbasque.com/fr/selon-mes-envies/culturelle/article-espelette-11.html"] },
    { id: "sarevillage", cat: "gor", area: "cevre", title: "Wander through the Basque village of Sare",
      desc: "Sare is a Labourd village at the foot of La Rhune, near the Spanish border, and is listed among the Plus Beaux Villages de France. It is the base for the Rhune rack railway and the prehistoric caves.",
      tip: "Sit on the fronton square, then continue to the caves or the train at Col de Saint-Ignace.", q: "Sare, Pyrénées-Atlantiques", tags: ["free"], src: ["https://www.tourisme64.com/nos-destinations/pays-basque/sare/"] },
    { id: "grottessare", cat: "gor", area: "cevre", title: "Descend into the Grottes de Sare",
      desc: "Limestone cave system at Sare with a developed route, an audio-visual guided tour of around 45 minutes to an hour, a museum and a megalithic park. The tour covers geology, prehistoric habitation and Basque origins, and runs in French, English, Basque and Spanish.",
      tip: "Book date, time and language online. It is open all year apart from a short winter closure, so confirm before going.", q: "Grottes Préhistoriques de Sare, Sare", tags: ["rainy day"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/sites-touristiques/grottes-et-gouffres/sare-78/les-grottes-de-sare-1226.html", "https://www.tourisme64.com/activites/sare/PCUAQU064FS0002V-grottes-prehistoriques-de-sare/"] },
    { id: "citadellesjpp", cat: "gor", area: "cevre", title: "Climb to the Vauban citadel of Saint-Jean-Pied-de-Port",
      desc: "The 17th-century citadel stands on the site of the old Navarrese royal castle, on the highest point of the town. Vauban inspected the town in 1680 and 1685. It now houses a school, but the cobbled climb up rue de la Citadelle gives a wide view over the town and hills.",
      tip: "Guided citadel visits run on selected dates. Walk up from the old town through the Porte Saint-Jacques.", q: "Citadelle, Saint-Jean-Pied-de-Port", tags: ["free"], src: ["https://sites-vauban.org/en/resources/vauban-site/saint-jean-pied-de-port", "https://monumentum.fr/monument-historique/pa00084506/saint-jean-pied-de-port-citadelle"] },
    { id: "chateaupau", cat: "gor", area: "cevre", title: "Tour the Château de Pau, birthplace of Henri IV",
      desc: "The Château de Pau is a national museum and domain, with a tapestry collection that includes eight pieces sent by Louis-Philippe in 1842. It became a national museum in 1929 and holds about 12,000 works and objects.",
      tip: "Check the museum website for closing days. Pair it with a walk along the Boulevard des Pyrénées.", q: "Château de Pau, Rue du Château, Pau", tags: ["rainy day"], src: ["https://www.tourisme64.com/activites/pau/PCUAQU064V508ZOE-musee-national-et-domaine-du-chateau-de-pau/", "https://en.wikipedia.com/wiki/Pau_Castle"] },
    { id: "paubvdpyrenees", cat: "gor", area: "cevre", title: "Watch the Pyrenees from the Boulevard des Pyrénées",
      desc: "Pau's panoramic promenade, opened between the château and the Palais Beaumont between 1893 and 1899, has a view of the Pyrenees from the Pic du Midi de Bigorre to the Pic du Midi d'Ossau on clear days. A viewing table helps name the peaks.",
      tip: "Go at sunset on a clear day. The funicular from the station arrives right here.", q: "Boulevard des Pyrénées, Pau", tags: ["free"], src: ["https://en.wikipedia.org/wiki/Boulevard_des_Pyr%C3%A9n%C3%A9es", "https://en.tourismepau.com/discover/pau-much-more-than-you-expected/pau-the-heart-of-the-city/boulevard-des-pyrenees/"] },
    { id: "oloroncathedral", cat: "gor", area: "cevre", title: "Study the Romanesque portal of Oloron cathedral",
      desc: "The Cathédrale Sainte-Marie in Oloron-Sainte-Marie keeps a sculpted Romanesque portal from about 1120 to 1140, sheltered by a bell-tower porch. Its tympanum shows the rare theme of the Descent from the Cross. It is part of the UNESCO Camino de Santiago routes in France.",
      tip: "Look closely at the tympanum figures. The building is now a parish church and is free to enter.", q: "Cathédrale Sainte-Marie, Place de la Cathédrale, Oloron-Sainte-Marie", tags: ["free", "rainy day"], src: ["https://en.wikipedia.com/wiki/Oloron_Cathedral", "https://pop.culture.gouv.fr/notice/merimee/PA00084466"] },
    { id: "navarrenxramparts", cat: "gor", area: "cevre", title: "Walk the 16th-century ramparts of Navarrenx",
      desc: "Navarrenx got its bastide charter in 1316, and its bastioned walls were started in 1538 under Henri d'Albret by the Italian engineer Fabricio Siciliano. The walls are about 1.66 km long and are classified monuments. The town held out in a siege in 1569.",
      tip: "The ramparts are free to walk; a loop of about 45 minutes is signposted. Visits led by the tourist office run in summer.", q: "Remparts de Navarrenx, Navarrenx", tags: ["free"], src: ["https://www.tourisme64.com/sur-place/itineraires/navarrenx/ITIAQU064V5CCGVK-la-cite-bastionnee/", "https://monumentum.fr/monument-historique/pa00084462/enceinte-bastionnee"] },
    { id: "orthezpontvieux", cat: "gor", area: "cevre", title: "Cross the medieval Pont Vieux at Orthez",
      desc: "The Pont Vieux dates from the 13th and 14th centuries, begun under Gaston VII de Moncade when he made Orthez the capital of Béarn. It has a tower, uneven arches and has been a listed monument since 1875. The Tour Moncade, remnant of the castle, stands nearby.",
      tip: "Walk it from the old town side, then continue to the Tour Moncade.", q: "Pont Vieux, Orthez", tags: ["free"], src: ["https://www.vinci-autoroutes.com/fr/decouvertes/idees-sorties/sites-touristiques/pont-vieux-dorthez/", "https://www.tourisme64.com/nos-destinations/bearn/orthez/"] },
    { id: "saliesbayaa", cat: "gor", area: "cevre", title: "Visit the salt spring crypt in Salies-de-Béarn",
      desc: "Salies-de-Béarn's brine is about ten times saltier than seawater. The Place du Bayaà has covered the town's salt spring since 1865, and a crypt beneath it, built to protect the source, can be visited. A salt museum in a 17th-century house tells the story.",
      tip: "Combine the crypt with the Musée du Sel; check the Béarn des Gaves tourist office for hours.", q: "Place du Bayaà, Salies-de-Béarn", tags: ["rainy day"], src: ["https://www.guide-tourisme-france.com/VISITER/crypte-bayaa--salies-bearn-37582.htm", "https://www.tourisme64.com/nos-destinations/bearn/salies-de-bearn/"] },
    { id: "sauveterretour", cat: "gor", area: "cevre", title: "Climb the Tour Monréal at Sauveterre-de-Béarn",
      desc: "The Tour Monréal is a tower over 30 metres tall on a rocky outcrop above the Gave d'Oloron. Sources date it to the 12th or 13th century, and it has been a museum since 2016. A riverside path leads down to the Pont de la Légende.",
      tip: "Walk down the stairs to the Pont de la Légende and the Île de la Glère afterwards.", q: "Tour Monréal, Sauveterre-de-Béarn", src: ["https://www.tourisme-bearn-gaves.com/en/discover/culture-and-heritage/self-guided-heritage-tours/sauveterre-de-bearn-step-into-the-legend/", "https://www.tourisme64.com/nos-destinations/bearn/sauveterre-de-bearn/"] },
    { id: "marquezeecomusee", cat: "gor", area: "cevre", title: "Ride the train to the Marquèze ecomuseum",
      desc: "Marquèze is an open-air museum in the Landes de Gascogne regional park, created in 1969, recreating 19th-century life in the Grande Lande. It is reached only by a small train from the former Sabres station and covers nearly 20 hectares. It is a Musée de France.",
      tip: "Seasonal: one guide lists 1 April to 27 September. Check marqueze.fr and allow half a day.", q: "Écomusée de Marquèze, Sabres", src: ["https://marqueze.fr/en/the-ecomusee-de-marqueze-history-and-aims.html", "https://www.tourismelandes.com/en/cultural-heritage/ecomuseum-of-marqueze-pcuaqu04001wb9r3/"] },
    { id: "montdemarsandonjon", cat: "gor", area: "cevre", title: "See sculpture in the Donjon Lacataye, Mont-de-Marsan",
      desc: "The Donjon Lacataye is a keep of the old castle, dated to the 14th or 15th century, and a listed monument since 1942. Since 1968 it has housed the Musée Despiau-Wlérick, devoted to sculptors Charles Despiau and Robert Wlérick of Mont-de-Marsan.",
      tip: "Opening hours were affected by works, so check beforehand. The address is Place Marguerite de Navarre.", q: "Donjon Lacataye, Place Marguerite de Navarre, Mont-de-Marsan", tags: ["rainy day"], src: ["https://en.wikipedia.org/wiki/Donjon_Lacataye", "https://monumentum.fr/musee-de-france/m0081/mont-de-marsan-musee-despiau-wlerick"] },
    { id: "daxfontainechaude", cat: "gor", area: "cevre", title: "Watch steam rise at Dax's Fontaine Chaude",
      desc: "The Fontaine Chaude is a monument over the source of the Nèhe spring, built 1814 to 1818 and listed since 1946. The water comes out at about 60 degrees and is still used by the town's thermal baths. Legend says a Roman legionnaire's dog was cured here.",
      tip: "It is free and open in the city centre. Come on a cold morning to see the steam.", q: "Fontaine Chaude, Place de la Fontaine Chaude, Dax", tags: ["free"], src: ["https://en.wikipedia.com/wiki/Fontaine_Chaude", "https://www.tourismelandes.com/patrimoine-culturel/la-fontaine-chaude/"] },
    { id: "pasderoland", cat: "gor", area: "cevre", title: "Find the Pas de Roland rock arch at Itxassou",
      desc: "The Pas de Roland is a natural rock passage cut by the Nive near Itxassou, tied to the legend of the knight Roland. It is free and open at all times and is reached on foot, about 2 km from the village, as part of loops such as the walk to Atharri.",
      tip: "Park in the village, as the road has no space. Wear shoes that cope with mud.", q: "Pas de Roland, Itxassou", tags: ["free"], src: ["https://www.guide-du-paysbasque.com/en/experiences/sport/article-stroll-between-nature-and-basque-legend-the-pas-de-roland-in-itxassou-108.html", "https://showcaves.com/english/fr/karst/PasDeRoland.html"] },
    { id: "lescuncirque", cat: "gor", area: "cevre", title: "Look up at the limestone peaks of Cirque de Lescun",
      desc: "The Cirque de Lescun is a glacial amphitheatre in the Vallée d'Aspe, inside the Pyrénées National Park. The village of Lescun sits at about 900 m on its slope, and the GR10 passes through. The Pic d'Anie and Pic du Billare rise above it.",
      tip: "Drive up from Oloron in about 45 minutes. Most trails start from the Anapia car park.", q: "Cirque de Lescun, Lescun", tags: ["free"], src: ["https://fr.wikipedia.org/wiki/Cirque_de_Lescun"] },
    { id: "ravelbirthplace", cat: "gor", area: "cevre", title: "Find Maurice Ravel's birthplace on Ciboure's quay",
      desc: "The house at 27 quai Maurice Ravel in Ciboure is where the composer was born on 7 March 1875. A shipowner built it in 1630, and Cardinal Mazarin stayed there in 1660 before Louis XIV's wedding. It is a listed monument and visible from outside only.",
      tip: "The interior is not open; look at it from the quay. Ciboure's old streets behind it are worth a wander.", q: "Maison de Ravel, 27 quai Maurice Ravel, Ciboure", tags: ["free"], src: ["https://monumentum.fr/monument-historique/pa00125257/ciboure-maison-de-ravel", "https://saint-jean-de-luz.com/en/sit/maison-natale-de-maurice-ravel/"] },
    { id: "urtubiechateau", cat: "gor", area: "cevre", title: "Tour the 14th-century Château d'Urtubie",
      desc: "Château d'Urtubie in Urrugne, about 3 km from Saint-Jean-de-Luz, dates from 1341 and has stayed in the same family. It is a listed monument with tapestries and a park, and also runs as a hotel.",
      tip: "Visits are paid and seasonal; check chateaudurtubie.net. The nearby coast is a short drive.", q: "Château d'Urtubie, Urrugne", tags: ["rainy day"], src: ["https://monumentum.fr/monument-historique/pa00084538/urrugne-chateau-durtubie", "https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/sites-touristiques/chateaux/saint-jean-de-luz-75/chateau-d-urtubie-1227.html"] },
    { id: "pariesgambetta", cat: "ye", area: "cevre", title: "Taste a mouchou at Maison Pariès",
      desc: "Pariès is a Basque confectioner on rue Gambetta in Saint-Jean-de-Luz, known for the mouchou, a soft almond cake (muxu means kiss in Basque), plus touron and kanougas. The house dates from 1895.",
      tip: "Buy mouchous and take a sit-down tea in the salon. Expect queues in summer.", q: "Maison Pariès, rue Gambetta, Saint-Jean-de-Luz", kind: "meal", src: ["https://www.guide-du-paysbasque.com/en/tourism/tasting/basque-products/cakes/saint-jean-de-luz-75/maison-paries-saint-jean-de-luz-3355.html", "https://www.gillespudlowski.com/critiques/paries"] },
    { id: "maisonadamsjdl", cat: "ye", area: "cevre", title: "Buy Basque macarons at Maison Adam",
      desc: "Maison Adam claims its macarons were served at Louis XIV's wedding in 1660 and that the recipe has passed down orally since then, through about 13 generations. The shop sits on place Louis XIV in Saint-Jean-de-Luz.",
      tip: "Try the classic Basque macaron, which is soft and chewy rather than crisp. Eat it fresh, as it softens in a day.", q: "Maison Adam, Place Louis XIV, Saint-Jean-de-Luz", kind: "sweet", src: ["https://maisonadam.fr/en/content/9-la-maison", "https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/artisans-visites-et-ateliers-/saint-jean-de-luz-75/maison-adam-6894.html"] },
    { id: "hallessjdl", cat: "ye", area: "cevre", title: "Graze the covered market of Saint-Jean-de-Luz",
      desc: "Les Halles on boulevard Victor Hugo sell line-caught fish, sheep cheese, gâteau basque and piment d'Espelette. A buvette inside serves oysters with wine. The covered market is open every morning, with extra outdoor stalls on Tuesdays and Fridays.",
      tip: "Arrive before 1 pm when stalls thin out. Buy a sheep cheese and a gâteau basque for a picnic.", q: "Les Halles, Boulevard Victor Hugo, Saint-Jean-de-Luz", kind: "snack", tags: ["rainy day"], src: ["https://www.saint-jean-de-luz.com/en/sit/marche-traditionnel-733/", "https://www.tourisme64.com/sur-place/agenda/saint-jean-de-luz/FMAAQU064V5CARYO-marche/"] },
    { id: "kaikusjdl", cat: "ye", area: "cevre", title: "Book a modern Basque tasting menu at Le Kaïku",
      desc: "Le Kaïku is a one-star Michelin restaurant at 17 rue de la République, a short walk from the port. Chef Nicolas Borombo trained at the Crillon and the George V and cooks modern Basque dishes with local produce. Gault&Millau gives it 15/20.",
      tip: "Reservation is needed, and it is closed Sunday and Monday according to listings. Expect roughly 58 to 128 euros per person.", q: "Le Kaïku, 17 rue de la République, Saint-Jean-de-Luz", kind: "meal", src: ["https://guide.michelin.com/en/nouvelle-aquitaine/saint-jean-de-luz/restaurant/le-kaiku", "https://fr.gaultmillau.com/en/restaurant/le-kaiku"] },
    { id: "ithurriaainhoa", cat: "ye", area: "cevre", title: "Dine at the starred Ithurria inn in Ainhoa",
      desc: "Ithurria is a family-run one-star Michelin inn on the Place du Fronton in Ainhoa, with chef Martin Isabal in the kitchen (Gault&Millau). Menus in the 2026 season run from 85 to 125 euros.",
      tip: "Book ahead. Combine it with a walk along Ainhoa's main street.", q: "Ithurria, Place du Fronton, Ainhoa", kind: "meal", src: ["https://guide.michelin.com/gb/en/nouvelle-aquitaine/ainhoa/restaurant/ithurria?millesime=um3g85", "https://www.tourisme64.com/en/restaurants/ainhoa/RESAQU064FS000IC-restaurant-ithurria/"] },
    { id: "ostapebidarray", cat: "ye", area: "cevre", title: "Eat farm-to-table at Lore Ttipia, Auberge Ostapé",
      desc: "Lore Ttipia is the one-star restaurant of Auberge Ostapé, a 17th-century farmstead on a country estate above Bidarray. Michelin describes modern cooking with farm-to-table produce, and Monday to Wednesday there is a simpler bistronomic menu.",
      tip: "Michelin shows it as a high price bracket. Book ahead; the bistronomic Monday-Wednesday menu is the cheaper way in.", q: "Auberge Ostapé, Domaine de Chahatoenia, Bidarray", kind: "meal", src: ["https://guide.michelin.com/en/nouvelle-aquitaine/bidarray/restaurant/lore-ttipia-auberge-ostape", "https://fr.gaultmillau.com/en/restaurant/auberge-ostape"] },
    { id: "agerriafromage", cat: "ye", area: "cevre", title: "Taste Ossau-Iraty sheep cheese at Ferme Agerria",
      desc: "Ferme Agerria in Saint-Martin-d'Arberoue is a family farm where the visit ends with a tasting of AOP Ossau-Iraty sheep's-milk cheese. It is one of many farms on the Ossau-Iraty cheese route.",
      tip: "Reservation is advised; the visit was priced around 6.50 euros for adults.", q: "Ferme Agerria, 430 Donapaleuko Errepidea, Saint-Martin-d'Arbéroue", kind: "snack", src: ["https://www.tourisme64.com/activites/saint-martin-darberoue/DEGAQU064FS00022-ferme-agerria/"] },
    { id: "puyodebatcambo", cat: "ye", area: "cevre", title: "Taste Basque chocolate at Puyodebat in Cambo",
      desc: "Chocolaterie Puyodebat in Cambo-les-Bains, on avenue de Navarre, combines a chocolate workshop, a museum and a shop. Founded by Christophe Puyodebat, it is recommended by tourism guides as Cambo's chocolate address.",
      tip: "Try the traditional Basque chocolates. Cambo also celebrates gâteau basque each autumn.", q: "Chocolaterie Puyodebat, Avenue de Navarre, Cambo-les-Bains", kind: "sweet", tags: ["rainy day"], src: ["https://www.tourisme64.com/en/immerse-yourself-in-the-world-of-chocolaterie-puyodebat-in-cambo-les-bains/", "https://www.en-pays-basque.fr/en/sit/chocolaterie-musee-boutique-puyodebat/"] },
    { id: "cavirouleguy", cat: "ye", area: "cevre", title: "Taste Irouléguy wine at the Cave d'Irouléguy",
      desc: "The cooperative cellar at Saint-Étienne-de-Baïgorry offers guided visits of the cellar and barrel room, ending with a tasting of the full range of Irouléguy cuvées. Slots run at 10:30 and 14:30, take about 1h30, and cost about 15 euros.",
      tip: "Booking is mandatory. Phone +33 5 59 37 41 33 or check cave-irouleguy.com for dates.", q: "Cave d'Irouléguy, Saint-Étienne-de-Baïgorry", kind: "drink", src: ["https://www.tourisme64.com/sur-place/agenda/saint-etienne-de-baigorry/FMAAQU064V5CF9JY-visite-decouverte-et-degustation-a-la-cave-dirouleguy/", "https://www.en-pays-basque.fr/wp-content/uploads/2024/03/plaquette-vd-annuaire-compresse-1.pdf"] },
    { id: "branasjpp", cat: "ye", area: "cevre", title: "Sip Williams pear eau-de-vie at Maison Brana",
      desc: "Brana has made wine and spirits in Saint-Jean-Pied-de-Port since 1897. Its tasting offer covers the distillery in Ossès, a shop on Place Floquet in the old town and the estate at Ispoure. The Williams pear eau-de-vie is the flagship.",
      tip: "Check brana.fr for visits and hours. The shop in the old town is the easiest stop.", q: "Maison Brana, Place Floquet, Saint-Jean-Pied-de-Port", kind: "meal", src: ["https://api-adresse.data.gouv.fr/search/?q=Place Floquet Saint-Jean-Pied-de-Port"] },
    { id: "cauhapemonein", cat: "ye", area: "cevre", title: "Taste dry and sweet Jurançon at Domaine Cauhapé",
      desc: "Domaine Cauhapé at Monein works about 50 ha of steep vineyards and makes dry and sweet Jurançon. Winalist lists a 30-minute tasting of five cuvées and a one-hour visit with tasting, both free for groups of up to 20.",
      tip: "Visits are by appointment, so phone +33 5 59 21 33 02 beforehand.", q: "Domaine Cauhapé, Quartier Castet, Monein", kind: "sweet", src: ["https://www.winalist.fr/hosts/590/domaine-cauhape", "https://www.ruedesvignerons.com/fr/domaine/1061/domaine-cauhape"] },
    { id: "miotpau", cat: "ye", area: "cevre", title: "Try the Coucougnettes du Vert Galant at Francis Miot",
      desc: "Francis Miot is a Pau confectioner, born in 1948, whose Coucougnettes are almonds in dark chocolate, rolled in marzipan flavoured with raspberry, ginger and Armagnac. They nod to Henri IV, nicknamed the Vert Galant. The Pau boutique is on rue Maréchal Joffre.",
      tip: "Buy a box in the Pau shop, or visit the workshops in Uzos.", q: "Maison Francis Miot, 46 rue Maréchal Joffre, Pau", kind: "meal", src: ["https://www.francis-miot.com/pages/15-boutique-pau", "https://maisondubiscuit.fr/en/chocolates/chocolate-candies/320-les-coucougnettes-3700416202247.html"] },
    { id: "hallespau", cat: "ye", area: "cevre", title: "Shop for Béarn produce at Les Halles de Pau",
      desc: "Pau's covered market has been on the same site since 1927, was renovated in 2018 and has about 40 local vendors focused on Béarn products. It has two floors with food and eating options.",
      tip: "Open Tuesday to Saturday 7 am to 1 pm and Sunday 9 am to 1 pm; the Nocturne evening opening is on the last Friday of the month.", q: "Les Halles de Pau, Place de la République, Pau", kind: "snack", tags: ["rainy day"], src: ["https://www.tourisme64.com/en/activities/pau/LOIAQU064V5B56OJ-les-halles-de-pau/", "https://en.tourismepau.com/discover/for-the-love-of-taste/shopping/covered-markets"] },
    { id: "ognoasarmagnac", cat: "ye", area: "cevre", title: "Taste Bas-Armagnac at Domaine d'Ognoas",
      desc: "The departmental Domaine d'Ognoas covers about 650 ha in Bas-Armagnac and has the oldest still in Gascony, from 1804, in a listed old cellar. The guided visit with tasting costs about 5 euros, and the shop sells Armagnac and Floc de Gascogne.",
      tip: "Hours change with the season, with only Tuesdays listed for October to December 2026. Check tourismelandes.com before driving.", q: "Domaine d'Ognoas, Arthez-d'Armagnac", kind: "meal", src: ["https://www.tourismelandes.com/en/degustation/domaine-departemental-dognoas-degaqu04001odhdl/", "https://www.tourismelandes.com/en/cultural-heritage/departmental-domain-dognoas-pcuaqu040fs0000u/"] },
    { id: "goustutcapbreton", cat: "ye", area: "cevre", title: "Order the day's catch at Goustut in Capbreton",
      desc: "Goustut is a fish-focused restaurant on the port of Capbreton run by chef Charles Guillou. Gault&Millau puts the price at 34 to 70 euros per person without drinks. The port still lands the fish it serves.",
      tip: "Book for dinner in season; look at the daily fish choices.", q: "Goustut, Port de Capbreton, Capbreton", kind: "meal", src: ["https://fr.gaultmillau.com/restaurant/goustut", "https://www.tourismelandes.com/en/a-restaurant/goustut-resaqu040v50kf7j/"] },
    { id: "chezvincentcapbreton", cat: "ye", area: "cevre", title: "Buy fish and eat it at Chez Vincent Côté Océan",
      desc: "Chez Vincent Côté Océan in Capbreton is both a fishmonger and a restaurant near the harbour. It is listed by Tourisme Landes among the port's restaurants serving locally landed fish.",
      tip: "Check opening days with the restaurant; the port also has a daily fish market nearby.", q: "Chez Vincent Côté Océan, 4 rue du Port d'Albret, Capbreton", kind: "meal", src: ["https://www.tourismelandes.com/restaurant/chez-vincent-cote-ocean-resaqu04001paeaa/"] },
    { id: "capbretonfishmarket", cat: "ye", area: "cevre", title: "Buy fish straight off the boats in Capbreton",
      desc: "Capbreton fishermen sell their catch on the quay every day, from 9 am to noon and 3 pm to 6 pm, without a fish auction. The custom goes back to a decree of Colbert that exempted Capbreton fishermen from the criée.",
      tip: "Go in the morning to see the choice. Ask what was landed that day.", q: "Marché aux poissons, Quai de la Pêcherie, Capbreton", kind: "snack", tags: ["free"], src: ["https://www.tourismelandes.com/marche-aux-poissons-port-de-capbreton", "https://www.guide-des-landes.com/fr/experiences/gourmande/article-le-marche-aux-poissons-de-capbreton-du-bateau-a-votre-assiette-118.html"] },
    { id: "vieuxchenechalosse", cat: "ye", area: "cevre", title: "Eat duck at the Ferme Auberge Le Vieux Chêne",
      desc: "Le Vieux Chêne is a farm inn in Castelnau-Chalosse that serves duck foie gras, magret, confit, garbure and salade landaise, with pasta made from farm wheat. It seats about 60 and is closed from December to February.",
      tip: "Outside winter it serves lunch at weekends; booking is advisable.", q: "Ferme auberge Le Vieux Chêne, 960 route de Dax, Castelnau-Chalosse", kind: "meal", src: ["https://www.tourismelandes.com/en/a-restaurant/farm-inn-the-old-oak-resaqu04001toxs2/"] },
    { id: "rhunetrain", cat: "dene", area: "cevre", title: "Ride the cog railway up La Rhune",
      desc: "The Petit train de la Rhune is a rack railway that has run from the Col de Saint-Ignace in Sare to the 905 m summit since 1924. The climb takes about 35 minutes, and it is one of four rack railways in service in France. New track was laid in 2023.",
      tip: "A return fare was listed at about 26 euros for adults. Take a jacket, as the summit is windier than the coast.", q: "Train de la Rhune, Col de Saint-Ignace, Sare", src: ["https://www.tourisme64.com/nos-destinations/pays-basque/incontournables-du-pays-basque/la-rhune/", "https://www.wikipedia.org/wiki/Petit_train_de_la_Rhune"] },
    { id: "graviere", cat: "dene", area: "cevre", title: "Watch surfers at La Gravière in Hossegor",
      desc: "La Gravière is one of the best-known beach breaks in Hossegor, heavy close to shore and tidal, and listed among the town's four world-class surf spots. The best surfers compete in Hossegor's autumn world championship stop.",
      tip: "Go in autumn or winter for the biggest waves. Park near the central beach and walk five minutes.", q: "Plage de la Gravière, Hossegor", tags: ["free"], src: ["https://www.tourismelandes.com/en/?p=12933", "https://www.hossegor.fr/en/le-surf"] },
    { id: "estagnotsseignosse", cat: "dene", area: "cevre", title: "Learn to surf at Les Estagnots in Seignosse",
      desc: "Les Estagnots is the best-known beach at Seignosse for surf, a supervised Blue Flag beach that hosts a world championship stage. Surf schools such as Surf Seignosse Paradise and Esta Surf School operate here. Summer swell is gentle enough for beginners.",
      tip: "Book a school lesson in summer; experienced surfers come in autumn.", q: "Plage des Estagnots, Seignosse", months: [6, 7, 8, 9], src: ["https://www.tourismelandes.com/loisir/plage-des-estagnots/", "https://www.seignosse-tourisme.com/en/sport-leisure/plage-des-estagnots-seignosse-en-3738698/"] },
    { id: "navarrosselake", cat: "dene", area: "cevre", title: "Swim at Navarrosse on Lac de Biscarrosse",
      desc: "Navarrosse is a supervised sandy beach lined by pines on the freshwater lake shared by Biscarrosse, Parentis, Gastes and Sainte-Eulalie. The lake is fed by the Canal des Landes and is not tidal, so swimming is possible at any hour.",
      tip: "Parking is paid in summer and only the left part of the beach is supervised.", q: "Plage de Navarrosse, Biscarrosse", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.guide-des-landes.com/en/tourism/discover/les-landes-beaches/biscarrosse-44/plage-de-navarrosse-au-lac-de-biscarosse-2746.html", "https://www.plages.tv/detail/plage-du-lac-de-navarrosse-biscarrosse-40600"] },
    { id: "courantdhuchet", cat: "dene", area: "cevre", title: "Glide down the Courant d'Huchet in a galupe",
      desc: "Boatmen at Léon take visitors in flat-bottomed galupes along the seven-kilometre Courant d'Huchet, which winds through dunes, bogs, pines and cork oaks to the sea at Moliets. Private boats, paddles and canoes are banned, so a guided boat is the only way.",
      tip: "Runs April to October. Bateliers: +33 5 58 48 75 39, site bateliers-courant-huchet.fr.", q: "Bateliers du Courant d'Huchet, Lac de Léon, Léon", months: [4, 5, 6, 7, 8, 9, 10], src: ["https://www.guide-des-landes.com/fr/tourisme/decouvrir/sites-touristiques/sites-naturels/leon-148/le-courant-d-huchet-1263.html", "https://www.guide-des-landes.com/fr/selon-mes-envies/culturelle/article-balade-insolite-en-barque-sur-le-courant-d-huchet--56.html"] },
    { id: "velodysseemimizan", cat: "dene", area: "cevre", title: "Cycle the Vélodyssée from Parentis to Mimizan-Plage",
      desc: "The Vélodyssée stage from Parentis-en-Born to Mimizan-Plage is about 31 km and takes around two hours by bike. It crosses the Sainte-Eulalie state forest and stops at the small port of Piaou before reaching the ocean.",
      tip: "The route passes a campsite closed at night, with listed gate hours. Rent bikes at Cycles en Born in Mimizan-Plage.", q: "Mimizan-Plage, Mimizan", tags: ["free"], src: ["https://www.francevelotourisme.com/etape/395", "https://www.tourismelandes.com/activite/cycles-en-born-location-de-velos-ascaqu040v50dhcc/"] },
    { id: "gourettebezou", cat: "dene", area: "cevre", title: "Hike from Gourette via the Bézou gondola",
      desc: "Gourette is a Pyrenean ski resort in the Ossau valley that is also used for summer hiking. The Bézou gondola runs from late June to 31 August and lets walkers start at altitude; the easy Bergerie walk takes about an hour.",
      tip: "Check the gondola's summer schedule before setting off. The GR10 gives a walk back down to the resort.", q: "Gourette, route de Gourette, Eaux-Bonnes", months: [6, 7, 8], src: ["https://fr.wikipedia.org/wiki/Gourette"] },
    { id: "artoustetrain", cat: "dene", area: "cevre", title: "Ride the Petit train d'Artouste to 2,000 m",
      desc: "The Petit train d'Artouste is reached by gondola from the Lac de Fabrèges and runs a loop of about 10 km in 55 minutes at 2,000 m. It was created in 1924 for dam works and has carried tourists since the 1930s. From the arrival, the lake is a 20 to 30 minute walk.",
      tip: "Runs May to October. Download your tickets in advance, as mobile coverage at Fabrèges is weak, and bring warm clothing.", q: "Télécabine d'Artouste, Lac de Fabrèges, Laruns", months: [5, 6, 7, 8, 9, 10], src: ["https://en.wikipedia.org/wiki/Petit_train_d%27Artouste", "https://www.tourisme64.com/activites/artouste/LOIAQU064FS000GR-lac-de-fabreges/"] },
    { id: "paufunicular", cat: "dene", area: "cevre", title: "Take the free funicular up to the Boulevard des Pyrénées",
      desc: "The Pau funicular links the railway station to the Boulevard des Pyrénées in the upper town. It dates from 1908 and is free to use, running every few minutes.",
      tip: "Check that it is running, as one article reported it out of service.", q: "Funiculaire de Pau, Place de la Gare, Pau", tags: ["free"], src: ["https://en.tourismepau.com/offers/le-funiculaire-pau-en-4904374", "https://en.wikipedia.org/wiki/Funiculaire_de_Pau"] },
    { id: "espelettepepperfest", cat: "dene", area: "cevre", title: "Join the Fête du Piment in Espelette",
      desc: "The Fête du Piment d'Espelette is held on the last weekend of October, with the 2026 edition on 24 and 25 October. Access is free and the village fills with stalls, processions and tastings.",
      tip: "Arrive early, as the village draws crowds. Check the programme with the town hall or the Confrérie.", q: "Fête du Piment, Espelette", months: [10], tags: ["free"], src: ["https://www.routard.com/fr/agenda/a/fete-du-piment-a-espelette", "https://www.festivalenfrance.com/festival/fete-du-piment-d-espelette"] },
    { id: "hendayegrandeplage", cat: "dene", area: "cevre", title: "Swim on the Grande Plage in Hendaye",
      desc: "Hendaye's Grande Plage is a supervised beach with views across the Bidassoa to Jaizkibel in Spain. Surf schools operate here, and the beach suits both beginners and experienced surfers.",
      tip: "Lifeguards patrol from June to September. Cycle tracks link the beach to the port and the Deux Jumeaux.", q: "Grande Plage, Hendaye", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/plages/hendaye-66/la-grande-plage-d-hendaye-6951.html", "https://www.tourisme64.com/nos-destinations/pays-basque/hendaye/"] },
    { id: "sjdlgrandeplage", cat: "dene", area: "cevre", title: "Swim on the sheltered Grande Plage of Saint-Jean-de-Luz",
      desc: "The Grande Plage is protected by a crescent of three sea walls, Artha, Sainte-Barbe and Socoa, built in the late 19th century. The beach is about a kilometre long, between the port and the Pergola quarter. In summer a boat shuttles from the Digue aux Chevaux to Socoa.",
      tip: "The sheltered water is good for families. Walk the promenade to Sainte-Barbe at sunset.", q: "Grande Plage, Saint-Jean-de-Luz", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.saint-jean-de-luz.com/en/sit/grande-plage-pergola-digue-aux-chevaux/", "https://ryo.co/fr/articles/france/biarritz/plage-saint-jean-luz/"] },
    { id: "guetharyparlementia", cat: "dene", area: "cevre", title: "Watch the surf at Parlementia in Guéthary",
      desc: "Guéthary is a village on the cliffs known for its reef waves. Parlementia, shared with Bidart, is a famous surf wave and a sandy beach supervised in summer, while Cenitz is the gentler neighbour.",
      tip: "Watch from the cliff or village. Lifeguards are present in July and August.", q: "Plage de Parlementia, Guéthary", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.pariszigzag.fr/?p=202400", "https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/plages/guethary-62/plage-de-cenitz-3583.html"] },
    { id: "bidarterretegia", cat: "dene", area: "cevre", title: "Start the coastal path at Erretegia beach, Bidart",
      desc: "Erretegia is a wilder, gravel-sand beach near Bidart centre, in a green setting, and the start of the coastal path to Hendaye, about 25 km. It has surf schools, lifeguards in summer and a small snack bar.",
      tip: "Reach it by bus or a short path with steps. The sentier du littoral beyond has closed sections, so check before long walks.", q: "Plage d'Erretegia, Bidart", months: [6, 7, 8, 9], tags: ["free"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/plages/bidart-54/plage-d-erretegia-3576.html", "https://www.tourisme64.com/en/activities/bidart/LOIAQU064FS000BI-plage-derretegia/"] },
    { id: "armaiteespadrilles", cat: "dene", area: "cevre", title: "Watch espadrilles made at Armaité",
      desc: "Armaité is an espadrille workshop at Idaux-Mendy, near Mauléon-Licharre, the espadrille capital of the Basque Country. The visit lasts 30 to 45 minutes and costs about 4 euros per person, by appointment.",
      tip: "Book on 05 59 28 33 61. Don Quichosse in Mauléon also has a workshop shop.", q: "Armaité, 1845 route d'Idaux, Idaux-Mendy", tags: ["rainy day"], src: ["https://www.guide-du-paysbasque.com/fr/tourisme/decouvrir/artisans-visites-et-ateliers-/idaux-mendy-21/armaite-4736.html"] },
    { id: "cambothermes", cat: "dene", area: "cevre", title: "Take the waters at the Thermes de Cambo-les-Bains",
      desc: "The thermal baths of Cambo-les-Bains use sulphur- and zinc-rich water that emerges at 22 degrees, recommended for rheumatology and respiratory care. The baths also welcome visitors who are not on a cure, with baths and water jets.",
      tip: "Check the Chaîne Thermale du Soleil website for prices and season dates.", q: "Thermes de Cambo-les-Bains, Cambo-les-Bains", tags: ["rainy day"], src: ["https://www.guide-du-paysbasque.com/fr/selon-mes-envies/detente/article-cure-thermale-a-cambo-les-bains-les-bienfaits-d-une-medecine-douce-naturelle-et-locale-123.html", "https://cirkwi.com/en/point-interet/885729-chaine-thermale-du-soleil-thermes-de-cambo-les-bains"] },
    { id: "holzartewalk", cat: "dene", area: "cevre", title: "Walk to the Holzarté suspension footbridge",
      desc: "The Passerelle d'Holzarté is a 70 m suspension footbridge above the Olhadubi gorge near Larrau, built in 1920 for woodcutters. It stands about 140 to 180 m above the gorge, depending on the source, and the wooden deck was replaced with metal.",
      tip: "The classic walk is about 1.9 km and an hour, with 183 m of ascent. Start from the Larrau car park.", q: "Passerelle d'Holzarté, Larrau", months: [5, 6, 7, 8, 9, 10], tags: ["free"], src: ["https://www.en-pays-basque.fr/en/sit/passerelle-dholzarte/", "https://www.guide-du-paysbasque.com/fr/experiences/incontournable/article-la-passerelle-d-holzarte-decouverte-vertigineuse-des-gorges-d-olhadubi-305.html"] },
    { id: "madeleinemdm", cat: "dene", area: "cevre", title: "Join the Fêtes de la Madeleine in Mont-de-Marsan",
      desc: "The Fêtes de la Madeleine are Mont-de-Marsan's July feria, five days and nights of concerts, parades and bullfights around the Arènes du Plumaçon and the town centre. The 2026 edition ran 22 to 26 July.",
      tip: "Dates change each year; check tourismelandes.com or the Régie des fêtes for the programme and tickets.", q: "Arènes du Plumaçon, Mont-de-Marsan", months: [7], src: ["https://www.tourismelandes.com/en/discover-the-destination/highlights/mont-de-marsan-festivals/", "https://www.festivalenfrance.com/festival/f-etes-de-la-madeleine-mont-de-marsan/2026"] },
    { id: "deuxjumeauxwalk", cat: "dene", area: "cevre", title: "Walk from the Deux Jumeaux to Pointe Sainte-Anne",
      desc: "An easy walk starts at the Deux Jumeaux station in Hendaye and heads to the Pointe Sainte-Anne, with viewpoints over the Deux Jumeaux rocks. The rocks lie off the Abbadia estate and can be reached at low tide.",
      tip: "Go at low tide. The old Corniche path across Ciboure, Urrugne and Hendaye was closed by a 2021 order, so keep to the signed route.", q: "Gare des Deux Jumeaux, Hendaye", tags: ["free"], src: ["https://www.visorando.com/randonnee-de-la-gare-des-deux-jumeaux-a-la-pointe-/", "https://www.france.fr/fr/article/sentier-du-littoral-basque-attention-les-yeux/"] }
  ]
